    function addFrame(x, y, w, h, name) {
        var tf = page.textFrames.add();
        tf.geometricBounds = [y, x, y + h, x + w];
        tf.label = name || "";
        return tf;
    }

    function addLine(x1, y1, x2, y2, strokeWt) {
        var g = page.graphicLines.add();
