```javascript
#target "InDesign"

(function () {
    if (app.documents.length === 0) {
        alert("No document open.");
        return;
    }

    var doc = app.activeDocument;
    var page = app.activeWindow.activePage;

    // =====================================
    // CONFIG
    // =====================================
    var CHECKBOX_SIZE = 0.11; // inches
    var CHECKBOX_STROKE = 0.6;
    var CHECKBOX_Y_OFFSET = 0.01; // tweak visually if needed
    var TARGET_FRAMES = ["Left Column", "Right Column"];
    var BOX_MARKER = "\u25A1\t"; // □ + tab
    var OBJECT_STYLE_NAME = "CS_Checkbox_Object";

    app.scriptPreferences.measurementUnit = MeasurementUnits.INCHES;

    // =====================================
    // HELPERS
    // =====================================
    function getObjectStyle(name) {
        var s;
        try {
            s = doc.objectStyles.itemByName(name);
            s.name;
            return s;
        } catch (e) {
            return null;
        }
    }

    function ensureObjectStyle(name) {
        var s;
        try {
            s = doc.objectStyles.itemByName(name);
            s.name;
        } catch (e) {
            s = doc.objectStyles.add({ name: name });
        }

        try { s.enableStroke = true; } catch (e1) {}
        try { s.strokeWeight = CHECKBOX_STROKE; } catch (e2) {}
        try { s.enableFill = true; } catch (e3) {}
        try { s.fillColor = doc.swatches.itemByName("None"); } catch (e4) {}
        try { s.strokeColor = doc.swatches.itemByName("Black"); } catch (e5) {}

        return s;
    }

    function frameIsTarget(tf) {
        for (var i = 0; i < TARGET_FRAMES.length; i++) {
            if (tf.label === TARGET_FRAMES[i]) return true;
        }
        return false;
    }

    function insertAnchoredCheckboxAtParagraphStart(paragraph, objStyle) {
        // Insert anchor at first insertion point of paragraph
        var ip = paragraph.insertionPoints[0];
        var rect = ip.rectangles.add();

        // Apply visual formatting
        try { rect.geometricBounds = [0, 0, CHECKBOX_SIZE, CHECKBOX_SIZE]; } catch (e) {}
        try { rect.strokeWeight = CHECKBOX_STROKE; } catch (e2) {}
        try { rect.strokeColor = doc.swatches.itemByName("Black"); } catch (e3) {}
        try { rect.fillColor = doc.swatches.itemByName("None"); } catch (e4) {}

        if (objStyle) {
            try { rect.appliedObjectStyle = objStyle; } catch (e5) {}
        }

        // Make it inline/anchored
        try {
            rect.anchoredObjectSettings.anchoredPosition = AnchorPosition.INLINE_POSITION;
        } catch (e6) {}

        // Fine tune vertical alignment
        try {
            rect.anchoredObjectSettings.anchorYoffset = CHECKBOX_Y_OFFSET;
        } catch (e7) {}

        // Some InDesign versions also allow x offset in inline use
        try {
            rect.anchoredObjectSettings.anchorXoffset = 0;
        } catch (e8) {}

        return rect;
    }

    function processParagraph(paragraph, objStyle) {
        var txt = paragraph.contents;

        if (txt.indexOf(BOX_MARKER) !== 0) return false;

        // Remove the leading square glyph only, keep the tab.
        // Before: "□\tDelay disguised as preparation"
        // After:  "\tDelay disguised as preparation"
        var newText = txt.replace(/^\u25A1/, "");
        paragraph.contents = newText;

        // Insert anchored box at paragraph start
        insertAnchoredCheckboxAtParagraphStart(paragraph, objStyle);

        return true;
    }

    function processFrame(tf, objStyle) {
        var count = 0;

        // Snapshot paragraphs because live collections can shift
        var paras = [];
        for (var i = 0; i < tf.paragraphs.length; i++) {
            paras.push(tf.paragraphs[i]);
        }

        for (var j = 0; j < paras.length; j++) {
            try {
                if (processParagraph(paras[j], objStyle)) count++;
            } catch (e) {}
        }

        return count;
    }

    // =====================================
    // MAIN
    // =====================================
    var objStyle = ensureObjectStyle(OBJECT_STYLE_NAME);
    var total = 0;

    for (var i = 0; i < page.textFrames.length; i++) {
        var tf = page.textFrames[i];
        if (frameIsTarget(tf)) {
            total += processFrame(tf, objStyle);
        }
    }

    alert("Checkbox conversion complete.\rConverted: " + total + " checklist items.");
})();
