## Unified JSX

```javascript
#target "InDesign"

(function () {
    if (app.documents.length === 0) {
        alert("No open document. Please open or create a document first.");
        return;
    }

    var doc = app.activeDocument;

    // -----------------------------
    // Config
    // -----------------------------
    var CHECK_STYLE_NAME = "CS_Check";
    var MARKER = "[CB]\t";

    var BOX_SIZE = 10;          // pt
    var BOX_STROKE = 0.75;      // pt
    var BOX_Y_OFFSET = 0;       // tweak if needed
    var BOX_X_OFFSET = 0;       // tweak if needed
    var SPACE_AFTER_BOX = "\u2009"; // thin space after anchor, optional

    // -----------------------------
    // Helpers
    // -----------------------------
    function getParagraphStyleByName(documentRef, styleName) {
        try {
            var ps = documentRef.paragraphStyles.itemByName(styleName);
            // Force resolution
            var n = ps.name;
            return ps;
        } catch (e) {
            return null;
        }
    }

    function startsWithMarker(paragraph, marker) {
        try {
            return paragraph.contents.indexOf(marker) === 0;
        } catch (e) {
            return false;
        }
    }

    function removeLeadingMarker(paragraph, marker) {
        // Removes exactly the marker characters only, preserving rest of formatting.
        try {
            var markerLength = marker.length;
            if (paragraph.characters.length >= markerLength) {
                paragraph.characters.itemByRange(0, markerLength - 1).remove();
                return true;
            }
        } catch (e) {}
        return false;
    }

    function insertAnchoredCheckboxAtStart(paragraph) {
        // Insert anchor point at paragraph start
        var insertionPoint = paragraph.insertionPoints[0];
        var anchoredRect = insertionPoint.rectangles.add();

        anchoredRect.geometricBounds = [0, 0, BOX_SIZE, BOX_SIZE];
        anchoredRect.strokeWeight = BOX_STROKE;
        anchoredRect.fillColor = doc.swatches.itemByName("None");
        anchoredRect.strokeColor = doc.swatches.itemByName("Black");

        // Inline anchored object
        anchoredRect.anchoredObjectSettings.anchoredPosition = AnchorPosition.INLINE_POSITION;
        anchoredRect.anchoredObjectSettings.anchorYoffset = BOX_Y_OFFSET;
        anchoredRect.anchoredObjectSettings.anchorXoffset = BOX_X_OFFSET;

        // Optional small space after object
        paragraph.insertionPoints[1].contents = SPACE_AFTER_BOX;

        return anchoredRect;
    }

    function paragraphAlreadyAnchored(paragraph) {
        // Optional guard: if paragraph already starts with an anchored object,
        // skip to avoid duplicates on rerun.
        try {
            var chars = paragraph.characters;
            if (chars.length === 0) return false;

            // If the first character is already an anchor marker, skip.
            // In InDesign, anchored objects appear as SpecialCharacters.ANCHOR_MARKER.
            return chars[0].contents === SpecialCharacters.ANCHOR_MARKER;
        } catch (e) {
            return false;
        }
    }

    // -----------------------------
    // Main
    // -----------------------------
    var checkStyle = getParagraphStyleByName(doc, CHECK_STYLE_NAME);
    if (!checkStyle) {
        alert("Paragraph style not found: " + CHECK_STYLE_NAME);
        return;
    }

    var changedCount = 0;
    var skippedCount = 0;

    app.doScript(function () {
        for (var s = 0; s < doc.stories.length; s++) {
            var story = doc.stories[s];
            var paragraphs = story.paragraphs;

            for (var p = 0; p < paragraphs.length; p++) {
                var para = paragraphs[p];

                try {
                    if (para.appliedParagraphStyle != checkStyle) {
                        continue;
                    }

                    if (paragraphAlreadyAnchored(para)) {
                        skippedCount++;
                        continue;
                    }

                    if (!startsWithMarker(para, MARKER)) {
                        continue;
                    }

                    if (!removeLeadingMarker(para, MARKER)) {
                        continue;
                    }

                    insertAnchoredCheckboxAtStart(para);
                    changedCount++;
                } catch (e) {
                    // Keep going if one paragraph is problematic
                }
            }
        }
    }, ScriptLanguage.JAVASCRIPT, undefined, UndoModes.ENTIRE_SCRIPT, "Convert checklist markers to anchored checkboxes");

    alert("Done.\nCheckboxes inserted: " + changedCount + "\nSkipped (already anchored): " + skippedCount);
})();
```

