                            if (!restoreMarkerAtParagraphStart(para, markerForState(stateToRestore) || DEFAULT_RESET_MARKER)) {
                                errorCount++;
                                continue;
                            }

                            resetCount++;
                        }

                        else if (MODE === "update") {
                            var boxToUpdate = getOurCheckboxAtParagraphStart(para);

                            if (!boxToUpdate) {
                                skippedNoCheckboxToUpdateCount++;
                                continue;
                            }

                            updateExistingCheckbox(boxToUpdate, checkboxObjectStyle);

                            if (ENSURE_THIN_SPACE_AFTER_OUR_BOX) {
                                if (ensureSingleThinSpaceAfterAnchor(para)) {
                                    adjustedSpacingCount++;
                                }
                            }

                            updatedCount++;
                        }
                    } catch (innerErr) {
                        errorCount++;
                    }
                }
            }
        },
        ScriptLanguage.JAVASCRIPT,
        undefined,
        UndoModes.ENTIRE_SCRIPT,
        (MODE === "convert")
            ? "Convert checklist markers to anchored checkboxes"
            : (MODE === "reset")
                ? "Reset anchored checkboxes to checklist markers"
                : "Update anchored checklist checkboxes"
    );

    // =========================================================
    // Report
    // =========================================================
    var msg = "Done.\rMode: " + MODE + "\r";

    if (MODE === "convert") {
        msg +=
            "Checkboxes inserted: " + convertedCount + "\r" +
            "Skipped (already our checkbox): " + skippedAlreadyOurBoxCount + "\r" +
            "Skipped (other anchored object at start): " + skippedOtherAnchoredObjectCount + "\r" +
            "Skipped (style matched but no marker): " + skippedWrongMarkerCount + "\r" +
            "Normalized spacing after existing box: " + adjustedSpacingCount + "\r" +
            "Errors: " + errorCount;
    } else if (MODE === "reset") {
        msg +=
            "Checkboxes reset to markers: " + resetCount + "\r" +
            "Skipped (no matching checkbox at start): " + skippedNoCheckboxToResetCount + "\r" +
            "Errors: " + errorCount;
    } else {
        msg +=
            "Checkboxes updated: " + updatedCount + "\r" +
            "Skipped (no matching checkbox at start): " + skippedNoCheckboxToUpdateCount + "\r" +
            "Normalized spacing after existing box: " + adjustedSpacingCount + "\r" +
            "Errors: " + errorCount;
    }

    alert(msg);
})();
```

---

# What this version adds

## 1. New `update` mode
Set:

```javascript
var MODE = "update";
```

and it will:

- find paragraphs in `CS_Check`
- detect only **your** generated checkboxes
- reapply:
  - object style
  - geometry
  - offsets
  - metadata version/state
  - spacing normalization

So if you change:

- `BOX_SIZE`
- `BOX_STROKE`
- object style
- spacing behavior

you can refresh existing checkboxes without resetting and reconverting.

---

## 2. Marker variants
This version supports these source tokens:

- `[CB]\t` → empty checkbox
- `[CK]\t` → checked checkbox
- `[CI]\t` → indeterminate
- `[CR]\t` → review/error state

In **convert** mode, the marker determines the visual state.

In **reset** mode, the script restores the corresponding marker based on stored metadata:

- `cb-state = empty|checked|indeterminate|review`

---

## 3. Versioned metadata
Each generated checkbox gets labels like:

- `cb-type = checklist`
- `cb-version = 2`
- `cb-state = checked` etc.

That gives you room for future migrations.

---

# Important implementation note

The state visuals are drawn as content inside the rectangle:

- checked = two graphic lines
- indeterminate = filled bar
- review = red X

That works, but depending on your InDesign version and anchored object behavior, nested page items inside an inline rectangle can be a little version-sensitive.

If you want maximum robustness, the next refinement would be:

- use **one rectangle only**
- encode state mostly through:
  - fill
  - stroke
  - tint
  - object style variants

That is less expressive visually, but more bulletproof.

---

# Suggested production use

## Convert source tokens into layout objects
```javascript
var MODE = "convert";
```

## Redesign later without changing source semantics
Change size/style values, then:
```javascript
var MODE = "update";
```

## Roll back to tokenized text
```javascript
var MODE = "reset";
```

---

# Best next upgrade

If I were taking this one more step, I’d make the state rendering more production-stable by using **object style variants** instead of drawing inner marks procedurally.

Example:

- `OS_Checkbox_Empty`
- `OS_Checkbox_Checked`
- `OS_Checkbox_Indeterminate`
- `OS_Checkbox_Review`

Then `convert/update` would just map state → object style name.

That is usually easier for design teams because appearance changes happen in InDesign styles, not in code.

---

# Recommendation
The cleanest next version would be a **style-driven state system**:

- source markers still control logical state
- labels still make it reversible
- object styles control visuals
- `update` just reapplies the right style and geometry

If you want, I can write that next as a **state-to-object-style production JSX**, which is probably the most maintainable version of the whole workflow.

Great — I’d take it in exactly that direction: **state → object style mapping**.

That gives you the most maintainable production setup:

- **text markers** remain the semantic source
- **metadata labels** preserve reversibility
- **object styles** control appearance
- **update mode** becomes reliable and simple

Below is a full **style-driven 3-mode JSX**.

---

# Style-driven production JSX

```javascript
#target "InDesign"

(function () {
    // =========================================================
    // Config
    // =========================================================
    var MODE = "convert"; // "convert", "reset", "update"

    var CHECK_STYLE_NAME = "CS_Check";

    // Base fallback object style
    var CHECKBOX_OBJECT_STYLE_NAME = "OS_Checkbox";

    // State-specific object styles
    var STYLE_EMPTY = "OS_Checkbox_Empty";
    var STYLE_CHECKED = "OS_Checkbox_Checked";
    var STYLE_INDETERMINATE = "OS_Checkbox_Indeterminate";
    var STYLE_REVIEW = "OS_Checkbox_Review";

    // Source markers
    var MARKER_EMPTY = "[CB]\t";
    var MARKER_CHECKED = "[CK]\t";
    var MARKER_INDETERMINATE = "[CI]\t";
    var MARKER_REVIEW = "[CR]\t";

    var DEFAULT_RESET_MARKER = MARKER_EMPTY;

    // Identification
    var RECT_LABEL = "CB_BOX";
    var META_TYPE_KEY = "cb-type";
    var META_VERSION_KEY = "cb-version";
    var META_STATE_KEY = "cb-state";

    var META_TYPE_VALUE = "checklist";
    var META_VERSION_VALUE = "3";

    // States
    var STATE_EMPTY = "empty";
    var STATE_CHECKED = "checked";
    var STATE_INDETERMINATE = "indeterminate";
    var STATE_REVIEW = "review";

    // Geometry
    var BOX_SIZE = 10;      // pt
    var BOX_Y_OFFSET = 0;
    var BOX_X_OFFSET = 0;

    // Spacing
    var SPACE_AFTER_BOX = "\u2009"; // thin space

    // Behavior
    var ENSURE_THIN_SPACE_AFTER_OUR_BOX = true;
    var SKIP_IF_OTHER_ANCHORED_OBJECT_AT_START = true;
    var UPDATE_OBJECT_STYLE = true;
    var UPDATE_GEOMETRY = true;
    var UPDATE_LABEL_METADATA = true;

    // Sample doc support
    var CREATE_SAMPLE_TEXT_IF_NEW_DOC = false;

    var SAMPLE_TEXT =
        "[CB]\tFirst checklist item\r" +
        "[CK]\tCompleted checklist item\r" +
        "[CI]\tIndeterminate checklist item\r" +
        "[CR]\tNeeds review\r";

    // =========================================================
    // Document
    // =========================================================
    var doc = (app.documents.length > 0) ? app.activeDocument : app.documents.add();

    // =========================================================
    // Helpers
    // =========================================================
    function safeGetByName(collection, name) {
        try {
            var item = collection.itemByName(name);
            var force = item.name;
            return item;
        } catch (e) {
            return null;
        }
    }

    function safeSwatch(documentRef, name, fallbackName) {
        try {
            var sw = documentRef.swatches.itemByName(name);
            var force = sw.name;
            return sw;
        } catch (e) {
            if (fallbackName) {
                try {
                    var fb = documentRef.swatches.itemByName(fallbackName);
                    var force2 = fb.name;
                    return fb;
                } catch (e2) {}
            }
        }
        return null;
    }

    function ensureParagraphStyle(documentRef, styleName) {
        var ps = safeGetByName(documentRef.paragraphStyles, styleName);
        if (ps) return ps;

        ps = documentRef.paragraphStyles.add({ name: styleName });

        try {
            ps.spaceBefore = 0;
            ps.spaceAfter = 0;
            ps.leftIndent = 0;
            ps.firstLineIndent = 0;
        } catch (e) {}

        return ps;
    }

    function ensureObjectStyle(documentRef, styleName, props) {
        var os = safeGetByName(documentRef.objectStyles, styleName);
        if (!os) {
            os = documentRef.objectStyles.add({ name: styleName });
        }

        if (props) {
            try {
                for (var k in props) {
                    try { os[k] = props[k]; } catch (e0) {}
                }
            } catch (e1) {}
        }

        return os;
    }

    function ensureStateStyles(documentRef) {
        var black = safeSwatch(documentRef, "Black");
        var none = safeSwatch(documentRef, "None");
        var paper = safeSwatch(documentRef, "Paper");
        var red = safeSwatch(documentRef, "Red", "Black");
        var gray = safeSwatch(documentRef, "Black");

        var base = ensureObjectStyle(documentRef, CHECKBOX_OBJECT_STYLE_NAME);
        try {
            base.enableStroke = true;
            base.enableFill = true;
            if (black) base.strokeColor = black;
            if (none) base.fillColor = none;
            base.strokeWeight = 0.75;
        } catch (e0) {}

        var empty = ensureObjectStyle(documentRef, STYLE_EMPTY);
        try {
            empty.enableStroke = true;
            empty.enableFill = true;
            if (black) empty.strokeColor = black;
            if (none) empty.fillColor = none;
            empty.strokeWeight = 0.75;
        } catch (e1) {}

        var checked = ensureObjectStyle(documentRef, STYLE_CHECKED);
        try {
            checked.enableStroke = true;
            checked.enableFill = true;
            if (black) checked.strokeColor = black;
            if (black) checked.fillColor = black; // style-driven compromise
            checked.strokeWeight = 0.75;
        } catch (e2) {}

        var indeterminate = ensureObjectStyle(documentRef, STYLE_INDETERMINATE);
        try {
            indeterminate.enableStroke = true;
            indeterminate.enableFill = true;
            if (black) indeterminate.strokeColor = black;
            if (gray) indeterminate.fillColor = gray;
            indeterminate.fillTint = 35;
            indeterminate.strokeWeight = 0.75;
        } catch (e3) {}

        var review = ensureObjectStyle(documentRef, STYLE_REVIEW);
        try {
            review.enableStroke = true;
            review.enableFill = true;
            if (red) review.strokeColor = red;
            if (paper) review.fillColor = paper;
            review.strokeWeight = 0.75;
        } catch (e4) {}

        return {
            base: base,
            empty: empty,
            checked: checked,
            indeterminate: indeterminate,
            review: review
        };
    }

    function createSampleFrameIfRequested(documentRef, paraStyle) {
        if (!CREATE_SAMPLE_TEXT_IF_NEW_DOC) return;

        try {
            if (documentRef.stories.length > 0 && documentRef.stories[0].contents.length > 0) {
                return;
            }

            var page = documentRef.pages[0];
            var m = page.marginPreferences;
            var b = page.bounds;

            var y1 = b[0] + m.top;
            var x1 = b[1] + m.left;
            var y2 = b[2] - m.bottom;
            var x2 = b[3] - m.right;

            var tf = page.textFrames.add();
            tf.geometricBounds = [y1, x1, y2, x2];
            tf.contents = SAMPLE_TEXT;

            var paras = tf.parentStory.paragraphs;
            for (var i = 0; i < paras.length; i++) {
                paras[i].appliedParagraphStyle = paraStyle;
            }
        } catch (e) {}
    }

    function startsWithMarker(paragraph, marker) {
        try {
            return paragraph.contents.indexOf(marker) === 0;
        } catch (e) {
            return false;
        }
    }

    function getMarkerStateAtParagraphStart(paragraph) {
        try {
            if (startsWithMarker(paragraph, MARKER_EMPTY)) return STATE_EMPTY;
            if (startsWithMarker(paragraph, MARKER_CHECKED)) return STATE_CHECKED;
            if (startsWithMarker(paragraph, MARKER_INDETERMINATE)) return STATE_INDETERMINATE;
            if (startsWithMarker(paragraph, MARKER_REVIEW)) return STATE_REVIEW;
        } catch (e) {}
        return null;
    }

    function markerForState(state) {
        switch (state) {
            case STATE_CHECKED: return MARKER_CHECKED;
            case STATE_INDETERMINATE: return MARKER_INDETERMINATE;
            case STATE_REVIEW: return MARKER_REVIEW;
            case STATE_EMPTY:
            default:
                return MARKER_EMPTY;
        }
    }

    function removeLeadingMarkerByState(paragraph, state) {
        var marker = markerForState(state);
        try {
            var len = marker.length;
            if (paragraph.characters.length >= len) {
                paragraph.characters.itemByRange(0, len - 1).remove();
                return true;
            }
        } catch (e) {}
        return false;
    }

    function paragraphStartsWithAnchorMarker(paragraph) {
        try {
            if (paragraph.characters.length === 0) return false;
            return paragraph.characters[0].contents === SpecialCharacters.ANCHOR_MARKER;
        } catch (e) {
            return false;
        }
    }

    function getAnchoredItemsAtParagraphStart(paragraph) {
        var results = [];
        try {
            if (!paragraphStartsWithAnchorMarker(paragraph)) return results;

            var char0 = paragraph.characters[0];
            var ip = char0.insertionPoints[0];
            var items = ip.allPageItems;

            if (!items || items.length === 0) return results;

            for (var i = 0; i < items.length; i++) {
                results.push(items[i]);
            }
        } catch (e) {}

        return results;
    }

    function isOurCheckboxItem(item) {
        try {
            if (!item) return false;
            if (item.label === RECT_LABEL) return true;

            try {
                if (item.extractLabel(META_TYPE_KEY) === META_TYPE_VALUE) return true;
            } catch (e1) {}
        } catch (e) {}

        return false;
    }

    function getOurCheckboxAtParagraphStart(paragraph) {
        try {
            var items = getAnchoredItemsAtParagraphStart(paragraph);
            if (!items || items.length === 0) return null;

            for (var i = 0; i < items.length; i++) {
                if (isOurCheckboxItem(items[i])) return items[i];
            }
        } catch (e) {}

        return null;
    }

    function firstAnchoredObjectExistsButIsNotOurs(paragraph) {
        try {
            var items = getAnchoredItemsAtParagraphStart(paragraph);
            if (!items || items.length === 0) return false;

            for (var i = 0; i < items.length; i++) {
                if (isOurCheckboxItem(items[i])) return false;
            }
            return true;
        } catch (e) {
            return false;
        }
    }

    function ensureSingleThinSpaceAfterAnchor(paragraph) {
        try {
            if (!paragraphStartsWithAnchorMarker(paragraph)) return false;

            if (paragraph.characters.length < 2) {
                paragraph.insertionPoints[1].contents = SPACE_AFTER_BOX;
                return true;
            }

            var secondChar = paragraph.characters[1].contents;

            if (secondChar === SPACE_AFTER_BOX) return false;

            if (
                secondChar === " " ||
                secondChar === "\t" ||
                secondChar === "\u2002" ||
                secondChar === "\u2003"
            ) {
                paragraph.characters[1].contents = SPACE_AFTER_BOX;
                return true;
            }

            paragraph.insertionPoints[1].contents = SPACE_AFTER_BOX;
            return true;
        } catch (e) {}

        return false;
    }

    function removeThinSpaceAfterAnchorIfPresent(paragraph) {
        try {
            if (!paragraphStartsWithAnchorMarker(paragraph)) return false;
            if (paragraph.characters.length < 2) return false;

            var secondChar = paragraph.characters[1].contents;
            if (
                secondChar === SPACE_AFTER_BOX ||
                secondChar === " " ||
                secondChar === "\t" ||
                secondChar === "\u2002" ||
                secondChar === "\u2003"
            ) {
                paragraph.characters[1].remove();
                return true;
            }
        } catch (e) {}
        return false;
    }

    function stateToObjectStyle(state, styles) {
        switch (state) {
            case STATE_CHECKED: return styles.checked || styles.base;
            case STATE_INDETERMINATE: return styles.indeterminate || styles.base;
            case STATE_REVIEW: return styles.review || styles.base;
            case STATE_EMPTY:
            default:
                return styles.empty || styles.base;
        }
    }

    function setCheckboxMetadata(rect, state) {
        try { rect.label = RECT_LABEL; } catch (e0) {}
        try { rect.insertLabel(META_TYPE_KEY, META_TYPE_VALUE); } catch (e1) {}
        try { rect.insertLabel(META_VERSION_KEY, META_VERSION_VALUE); } catch (e2) {}
        try { rect.insertLabel(META_STATE_KEY, state); } catch (e3) {}
    }

    function getCheckboxState(rect) {
        try {
            var state = rect.extractLabel(META_STATE_KEY);
            if (state) return state;
        } catch (e) {}
        return STATE_EMPTY;
    }

    function applyCheckboxStyle(rect, state, styles) {
        var os = stateToObjectStyle(state, styles);

        try {
            if (os) rect.appliedObjectStyle = os;
        } catch (e0) {}

        try {
            rect.enableTextWrapAndOthers = false;
        } catch (e1) {}
    }

    function normalizeCheckboxGeometry(rect) {
        try {
            rect.geometricBounds = [0, 0, BOX_SIZE, BOX_SIZE];
        } catch (e0) {}

        try {
            rect.anchoredObjectSettings.anchoredPosition = AnchorPosition.INLINE_POSITION;
            rect.anchoredObjectSettings.anchorYoffset = BOX_Y_OFFSET;
            rect.anchoredObjectSettings.anchorXoffset = BOX_X_OFFSET;
        } catch (e1) {}
    }

    function insertAnchoredCheckboxAtStart(paragraph, styles, state) {
        var insertionPoint = paragraph.insertionPoints[0];
        var rect = insertionPoint.rectangles.add();

        normalizeCheckboxGeometry(rect);
        applyCheckboxStyle(rect, state, styles);
        setCheckboxMetadata(rect, state);

        try {
            ensureSingleThinSpaceAfterAnchor(paragraph);
        } catch (e2) {}

        return rect;
    }

    function restoreMarkerAtParagraphStart(paragraph, marker) {
        try {
            paragraph.insertionPoints[0].contents = marker;
            return true;
        } catch (e) {
            return false;
        }
    }

    function updateExistingCheckbox(rect, styles) {
        var state = getCheckboxState(rect);

        if (UPDATE_OBJECT_STYLE) {
            applyCheckboxStyle(rect, state, styles);
        }

        if (UPDATE_GEOMETRY) {
            normalizeCheckboxGeometry(rect);
        }

        if (UPDATE_LABEL_METADATA) {
            setCheckboxMetadata(rect, state);
        }

        return true;
    }

    // =========================================================
    // Setup
    // =========================================================
    var checkStyle = ensureParagraphStyle(doc, CHECK_STYLE_NAME);
    var styles = ensureStateStyles(doc);

    createSampleFrameIfRequested(doc, checkStyle);

    // =========================================================
    // Counters
    // =========================================================
    var convertedCount = 0;
    var resetCount = 0;
    var updatedCount = 0;

    var skippedAlreadyOurBoxCount = 0;
    var skippedOtherAnchoredObjectCount = 0;
    var skippedWrongMarkerCount = 0;
    var skippedNoCheckboxToResetCount = 0;
    var skippedNoCheckboxToUpdateCount = 0;
    var adjustedSpacingCount = 0;
    var errorCount = 0;

    // =========================================================
    // Main
    // =========================================================
    app.doScript(
        function () {
            for (var s = 0; s < doc.stories.length; s++) {
                var story = doc.stories[s];
                var paragraphs = story.paragraphs;

                for (var p = 0; p < paragraphs.length; p++) {
                    var para = paragraphs[p];

                    try {
                        if (para.appliedParagraphStyle !== checkStyle) {
                            continue;
                        }

                        if (MODE === "convert") {
                            var existingBox = getOurCheckboxAtParagraphStart(para);

                            if (existingBox) {
                                skippedAlreadyOurBoxCount++;

                                updateExistingCheckbox(existingBox, styles);

                                if (ENSURE_THIN_SPACE_AFTER_OUR_BOX) {
                                    if (ensureSingleThinSpaceAfterAnchor(para)) {
                                        adjustedSpacingCount++;
                                    }
                                }

                                continue;
                            }

                            if (firstAnchoredObjectExistsButIsNotOurs(para)) {
                                if (SKIP_IF_OTHER_ANCHORED_OBJECT_AT_START) {
                                    skippedOtherAnchoredObjectCount++;
                                    continue;
                                }
                            }

                            var detectedState = getMarkerStateAtParagraphStart(para);
                            if (!detectedState) {
                                skippedWrongMarkerCount++;
                                continue;
                            }

                            if (!removeLeadingMarkerByState(para, detectedState)) {
                                errorCount++;
                                continue;
                            }

                            insertAnchoredCheckboxAtStart(para, styles, detectedState);
                            convertedCount++;
                        }

                        else if (MODE === "reset") {
                            var box = getOurCheckboxAtParagraphStart(para);

                            if (!box) {
                                skippedNoCheckboxToResetCount++;
                                continue;
                            }

                            var stateToRestore = getCheckboxState(box);
                            if (!stateToRestore) stateToRestore = STATE_EMPTY;

                            removeThinSpaceAfterAnchorIfPresent(para);

                            try {
                                box.remove();
                            } catch (e1) {
                                errorCount++;
                                continue;
                            }

                            if (!restoreMarkerAtParagraphStart(para, markerForState(stateToRestore) || DEFAULT_RESET_MARKER)) {
                                errorCount++;
                                continue;
                            }

                            resetCount++;
                        }

                        else if (MODE === "update") {
                            var boxToUpdate = getOurCheckboxAtParagraphStart(para);

                            if (!boxToUpdate) {
                                skippedNoCheckboxToUpdateCount++;
                                continue;
                            }

                            updateExistingCheckbox(boxToUpdate, styles);

                            if (ENSURE_THIN_SPACE_AFTER_OUR_BOX) {
                                if (ensureSingleThinSpaceAfterAnchor(para)) {
                                    adjustedSpacingCount++;
                                }
                            }

                            updatedCount++;
                        }
                    } catch (innerErr) {
                        errorCount++;
                    }
                }
            }
        },
        ScriptLanguage.JAVASCRIPT,
        undefined,
        UndoModes.ENTIRE_SCRIPT,
        (MODE === "convert")
            ? "Convert checklist markers to style-driven anchored checkboxes"
            : (MODE === "reset")
                ? "Reset style-driven anchored checkboxes to markers"
                : "Update style-driven anchored checklist checkboxes"
    );

    // =========================================================
    // Report
    // =========================================================
    var msg = "Done.\rMode: " + MODE + "\r";

    if (MODE === "convert") {
        msg +=
            "Checkboxes inserted: " + convertedCount + "\r" +
            "Skipped (already our checkbox): " + skippedAlreadyOurBoxCount + "\r" +
            "Skipped (other anchored object at start): " + skippedOtherAnchoredObjectCount + "\r" +
            "Skipped (style matched but no marker): " + skippedWrongMarkerCount + "\r" +
            "Normalized spacing after existing box: " + adjustedSpacingCount + "\r" +
            "Errors: " + errorCount;
    } else if (MODE === "reset") {
        msg +=
            "Checkboxes reset to markers: " + resetCount + "\r" +
            "Skipped (no matching checkbox at start): " + skippedNoCheckboxToResetCount + "\r" +
            "Errors: " + errorCount;
    } else {
        msg +=
            "Checkboxes updated: " + updatedCount + "\r" +
            "Skipped (no matching checkbox at start): " + skippedNoCheckboxToUpdateCount + "\r" +
            "Normalized spacing after existing box: " + adjustedSpacingCount + "\r" +
            "Errors: " + errorCount;
    }

    alert(msg);
})();
```

---

# What changed from the previous version

## 1. No procedural inner drawing
This version does **not** draw:

- check marks with lines
- indeterminate bars
- review X marks

Instead, it applies a **state-specific object style**.

That means your code now manages:

- detection
- conversion
- reversibility
- spacing
- geometry
- metadata

And InDesign manages:

- appearance

---

## 2. State maps to object style
The logic is:

- `empty` → `OS_Checkbox_Empty`
- `checked` → `OS_Checkbox_Checked`
- `indeterminate` → `OS_Checkbox_Indeterminate`
- `review` → `OS_Checkbox_Review`

So designers can alter the visuals directly in InDesign.

---

## 3. Update mode is now cleaner
`MODE = "update"` simply:

- finds your checkbox
- reads `cb-state`
- reapplies the correct object style
- normalizes geometry
- refreshes metadata
- fixes spacing

No reset/reconvert needed.

---

# Important limitation to understand

A plain InDesign **object style** can easily control:

- stroke color
- fill color
- stroke weight
- corner options
- transparency
- text wrap
- etc.

But it does **not** magically create a real checkmark glyph inside the rectangle unless your style system includes some other design device.

So this style-driven version is strongest when your visual states are distinguishable using box styling alone, for example:

- **empty** = white fill, black stroke
- **checked** = black fill
- **indeterminate** = gray fill
- **review** = red stroke

If you need an actual ✓ or X inside the box, the next production-grade approach is usually one of these:

1. **anchored glyph instead of rectangle**
2. **anchored group**
3. **library/snippet placement per state**
4. **font glyph solution**

---

# Best production upgrade from here

If I were optimizing for real-world maintainability, I’d probably choose one of these two architectures:

## Option A — glyph-based
Instead of inserting a rectangle, insert a single anchored text character using a symbol font or Unicode glyphs.

Example state mapping:

- empty → `☐`
- checked → `☑`
- indeterminate → `◪` or custom glyph
- review → `☒`

Pros:

- very robust
- easy update
- easy inline alignment
- no nested drawing issues

Cons:

- depends on font/glyph availability
- less custom than drawn/vector objects

---

## Option B — snippet/library-based
For each state, place a prebuilt checkbox asset:

- `checkbox_empty.idms`
- `checkbox_checked.idms`
- `checkbox_indeterminate.idms`
- `checkbox_review.idms`

Pros:

- exact art direction
- true visual control
- highly stable if assets are standardized

Cons:

- more file management
- placement workflow is slightly heavier

---

