# Glyph-based reversible checklist JSX

```javascript
#target "InDesign"

(function () {
    // =========================================================
    // Config
    // =========================================================
    var MODE = "convert"; // "convert", "reset", "update"

    var CHECK_PARAGRAPH_STYLE_NAME = "CS_Check";
    var CHECK_GLYPH_CHARACTER_STYLE_NAME = "CH_CheckGlyph";

    // Markers
    var MARKER_EMPTY = "[CB]\t";
    var MARKER_CHECKED = "[CK]\t";
    var MARKER_INDETERMINATE = "[CI]\t";
    var MARKER_REVIEW = "[CR]\t";

    // States
    var STATE_EMPTY = "empty";
    var STATE_CHECKED = "checked";
    var STATE_INDETERMINATE = "indeterminate";
    var STATE_REVIEW = "review";

    // Glyphs
    var GLYPH_EMPTY = "☐";
    var GLYPH_CHECKED = "☑";
    var GLYPH_INDETERMINATE = "◩";
    var GLYPH_REVIEW = "☒";

    var SPACE_AFTER_GLYPH = "\u2009"; // thin space
    var DEFAULT_RESET_MARKER = MARKER_EMPTY;

    // Metadata
    var META_TYPE_KEY = "cb-type";
    var META_VERSION_KEY = "cb-version";
    var META_STATE_KEY = "cb-state";

    var META_TYPE_VALUE = "checklist-glyph";
    var META_VERSION_VALUE = "1";

    // Behavior
    var ENSURE_SPACE_AFTER_GLYPH = true;
    var UPDATE_GLYPH_CONTENT = true;
    var UPDATE_CHARACTER_STYLE = true;
    var UPDATE_METADATA = true;

    // =========================================================
    // Document
    // =========================================================
    var doc = (app.documents.length > 0) ? app.activeDocument : app.documents.add();

    // =========================================================
    // Helpers
    // =========================================================
    function safeGetByName(collection, name) {
        try {
            var item = collection.itemByName(name);
            var force = item.name;
            return item;
        } catch (e) {
            return null;
        }
    }

    function safeSwatch(documentRef, name, fallbackName) {
        try {
            var sw = documentRef.swatches.itemByName(name);
            var force = sw.name;
            return sw;
        } catch (e) {
            if (fallbackName) {
                try {
                    var fb = documentRef.swatches.itemByName(fallbackName);
                    var force2 = fb.name;
                    return fb;
                } catch (e2) {}
            }
        }
        return null;
    }

    function ensureParagraphStyle(documentRef, styleName) {
        var ps = safeGetByName(documentRef.paragraphStyles, styleName);
        if (ps) return ps;

        ps = documentRef.paragraphStyles.add({ name: styleName });
        return ps;
    }

    function ensureCharacterStyle(documentRef, styleName) {
        var cs = safeGetByName(documentRef.characterStyles, styleName);
        if (cs) return cs;

        cs = documentRef.characterStyles.add({ name: styleName });

        try {
            var black = safeSwatch(documentRef, "Black");
            if (black) cs.fillColor = black;
        } catch (e) {}

        return cs;
    }

    function startsWithMarker(paragraph, marker) {
        try {
            return paragraph.contents.indexOf(marker) === 0;
        } catch (e) {
            return false;
        }
    }

    function getMarkerStateAtParagraphStart(paragraph) {
        try {
            if (startsWithMarker(paragraph, MARKER_EMPTY)) return STATE_EMPTY;
            if (startsWithMarker(paragraph, MARKER_CHECKED)) return STATE_CHECKED;
            if (startsWithMarker(paragraph, MARKER_INDETERMINATE)) return STATE_INDETERMINATE;
            if (startsWithMarker(paragraph, MARKER_REVIEW)) return STATE_REVIEW;
        } catch (e) {}
        return null;
    }

    function markerForState(state) {
        switch (state) {
            case STATE_CHECKED: return MARKER_CHECKED;
            case STATE_INDETERMINATE: return MARKER_INDETERMINATE;
            case STATE_REVIEW: return MARKER_REVIEW;
            case STATE_EMPTY:
            default:
                return MARKER_EMPTY;
        }
    }

    function glyphForState(state) {
        switch (state) {
            case STATE_CHECKED: return GLYPH_CHECKED;
            case STATE_INDETERMINATE: return GLYPH_INDETERMINATE;
            case STATE_REVIEW: return GLYPH_REVIEW;
            case STATE_EMPTY:
            default:
                return GLYPH_EMPTY;
        }
    }

    function stateForGlyph(ch) {
        if (ch === GLYPH_EMPTY) return STATE_EMPTY;
        if (ch === GLYPH_CHECKED) return STATE_CHECKED;
        if (ch === GLYPH_INDETERMINATE) return STATE_INDETERMINATE;
        if (ch === GLYPH_REVIEW) return STATE_REVIEW;
        return null;
    }

    function removeLeadingMarkerByState(paragraph, state) {
        var marker = markerForState(state);
        try {
            var len = marker.length;
            if (paragraph.characters.length >= len) {
                paragraph.characters.itemByRange(0, len - 1).remove();
                return true;
            }
        } catch (e) {}
        return false;
    }

    function setGlyphMetadata(characterRef, state) {
        try { characterRef.insertLabel(META_TYPE_KEY, META_TYPE_VALUE); } catch (e0) {}
        try { characterRef.insertLabel(META_VERSION_KEY, META_VERSION_VALUE); } catch (e1) {}
        try { characterRef.insertLabel(META_STATE_KEY, state); } catch (e2) {}
    }

    function isOurGlyphCharacter(characterRef) {
        try {
            if (!characterRef || !characterRef.isValid) return false;

            var t = characterRef.extractLabel(META_TYPE_KEY);
            if (t === META_TYPE_VALUE) return true;

            var state = stateForGlyph(characterRef.contents);
            if (state) {
                try {
                    if (characterRef.appliedCharacterStyle && characterRef.appliedCharacterStyle.name === CHECK_GLYPH_CHARACTER_STYLE_NAME) {
                        return true;
                    }
                } catch (e1) {}
            }
        } catch (e) {}

        return false;
    }

    function getLeadingGlyphCharacter(paragraph) {
        try {
            if (paragraph.characters.length < 1) return null;
            var ch = paragraph.characters[0];
            if (isOurGlyphCharacter(ch)) return ch;
        } catch (e) {}
        return null;
    }

    function getGlyphState(characterRef) {
        try {
            var state = characterRef.extractLabel(META_STATE_KEY);
            if (state) return state;
        } catch (e) {}

        try {
            return stateForGlyph(characterRef.contents) || STATE_EMPTY;
        } catch (e2) {}

        return STATE_EMPTY;
    }

    function ensureSingleThinSpaceAfterGlyph(paragraph) {
        try {
            if (paragraph.characters.length < 1) return false;

            var first = paragraph.characters[0];
            if (!isOurGlyphCharacter(first)) return false;

            if (paragraph.characters.length < 2) {
                paragraph.insertionPoints[1].contents = SPACE_AFTER_GLYPH;
                return true;
            }

            var secondChar = paragraph.characters[1].contents;

            if (secondChar === SPACE_AFTER_GLYPH) return false;

            if (
                secondChar === " " ||
                secondChar === "\t" ||
                secondChar === "\u2002" ||
                secondChar === "\u2003"
            ) {
                paragraph.characters[1].contents = SPACE_AFTER_GLYPH;
                return true;
            }

            paragraph.insertionPoints[1].contents = SPACE_AFTER_GLYPH;
            return true;
        } catch (e) {}

        return false;
    }

    function removeSpaceAfterGlyphIfPresent(paragraph) {
        try {
            if (paragraph.characters.length < 2) return false;
            if (!isOurGlyphCharacter(paragraph.characters[0])) return false;

            var secondChar = paragraph.characters[1].contents;
            if (
                secondChar === SPACE_AFTER_GLYPH ||
                secondChar === " " ||
                secondChar === "\t" ||
                secondChar === "\u2002" ||
                secondChar === "\u2003"
            ) {
                paragraph.characters[1].remove();
                return true;
            }
        } catch (e) {}
        return false;
    }

    function insertGlyphAtParagraphStart(paragraph, charStyle, state) {
        var glyph = glyphForState(state);

        try {
            paragraph.insertionPoints[0].contents = glyph;
            var ch = paragraph.characters[0];

            try { ch.appliedCharacterStyle = charStyle; } catch (e1) {}
            setGlyphMetadata(ch, state);

            if (ENSURE_SPACE_AFTER_GLYPH) {
                ensureSingleThinSpaceAfterGlyph(paragraph);
            }

            return ch;
        } catch (e) {
            return null;
        }
    }

    function restoreMarkerAtParagraphStart(paragraph, marker) {
        try {
            paragraph.insertionPoints[0].contents = marker;
            return true;
        } catch (e) {
            return false;
        }
    }

    function updateExistingGlyph(characterRef, charStyle) {
        var state = getGlyphState(characterRef);

        if (UPDATE_GLYPH_CONTENT) {
            try {
                characterRef.contents = glyphForState(state);
            } catch (e0) {}
        }

        if (UPDATE_CHARACTER_STYLE) {
            try {
                characterRef.appliedCharacterStyle = charStyle;
            } catch (e1) {}
        }

        if (UPDATE_METADATA) {
            setGlyphMetadata(characterRef, state);
        }

        return true;
    }

    // =========================================================
    // Setup
    // =========================================================
    var checkParaStyle = ensureParagraphStyle(doc, CHECK_PARAGRAPH_STYLE_NAME);
    var glyphCharStyle = ensureCharacterStyle(doc, CHECK_GLYPH_CHARACTER_STYLE_NAME);

    // =========================================================
    // Counters
    // =========================================================
    var convertedCount = 0;
    var resetCount = 0;
    var updatedCount = 0;

    var skippedAlreadyConvertedCount = 0;
    var skippedWrongMarkerCount = 0;
    var skippedNoGlyphToResetCount = 0;
    var skippedNoGlyphToUpdateCount = 0;
    var adjustedSpacingCount = 0;
    var errorCount = 0;

    // =========================================================
    // Main
    // =========================================================
    app.doScript(
        function () {
            for (var s = 0; s < doc.stories.length; s++) {
                var story = doc.stories[s];
                var paragraphs = story.paragraphs;

                for (var p = 0; p < paragraphs.length; p++) {
                    var para = paragraphs[p];

                    try {
                        if (para.appliedParagraphStyle !== checkParaStyle) {
                            continue;
                        }

                        if (MODE === "convert") {
                            var existingGlyph = getLeadingGlyphCharacter(para);

                            if (existingGlyph) {
                                skippedAlreadyConvertedCount++;
                                updateExistingGlyph(existingGlyph, glyphCharStyle);

                                if (ENSURE_SPACE_AFTER_GLYPH) {
                                    if (ensureSingleThinSpaceAfterGlyph(para)) {
                                        adjustedSpacingCount++;
                                    }
                                }
                                continue;
                            }

                            var detectedState = getMarkerStateAtParagraphStart(para);
                            if (!detectedState) {
                                skippedWrongMarkerCount++;
                                continue;
                            }

                            if (!removeLeadingMarkerByState(para, detectedState)) {
                                errorCount++;
                                continue;
                            }

                            var inserted = insertGlyphAtParagraphStart(para, glyphCharStyle, detectedState);
                            if (!inserted) {
                                errorCount++;
                                continue;
                            }

                            convertedCount++;
                        }

                        else if (MODE === "reset") {
                            var glyphChar = getLeadingGlyphCharacter(para);

                            if (!glyphChar) {
                                skippedNoGlyphToResetCount++;
                                continue;
                            }

                            var stateToRestore = getGlyphState(glyphChar);
                            if (!stateToRestore) stateToRestore = STATE_EMPTY;

                            removeSpaceAfterGlyphIfPresent(para);

                            try {
                                glyphChar.remove();
                            } catch (e1) {
                                errorCount++;
                                continue;
                            }

                            if (!restoreMarkerAtParagraphStart(para, markerForState(stateToRestore) || DEFAULT_RESET_MARKER)) {
                                errorCount++;
                                continue;
                            }

                            resetCount++;
                        }

                        else if (MODE === "update") {
                            var glyphToUpdate = getLeadingGlyphCharacter(para);

                            if (!glyphToUpdate) {
                                skippedNoGlyphToUpdateCount++;
                                continue;
                            }

                            updateExistingGlyph(glyphToUpdate, glyphCharStyle);

                            if (ENSURE_SPACE_AFTER_GLYPH) {
                                if (ensureSingleThinSpaceAfterGlyph(para)) {
                                    adjustedSpacingCount++;
                                }
                            }

                            updatedCount++;
                        }
                    } catch (innerErr) {
                        errorCount++;
                    }
                }
            }
        },
        ScriptLanguage.JAVASCRIPT,
        undefined,
        UndoModes.ENTIRE_SCRIPT,
        (MODE === "convert")
            ? "Convert checklist markers to glyph checklist items"
            : (MODE === "reset")
                ? "Reset glyph checklist items to markers"
                : "Update glyph checklist items"
    );

    // =========================================================
    // Report
    // =========================================================
    var msg = "Done.\rMode: " + MODE + "\r";

    if (MODE === "convert") {
        msg +=
            "Glyph checkboxes inserted: " + convertedCount + "\r" +
            "Skipped (already converted): " + skippedAlreadyConvertedCount + "\r" +
            "Skipped (style matched but no marker): " + skippedWrongMarkerCount + "\r" +
            "Normalized spacing: " + adjustedSpacingCount + "\r" +
            "Errors: " + errorCount;
    } else if (MODE === "reset") {
        msg +=
            "Glyph checkboxes reset to markers: " + resetCount + "\r" +
            "Skipped (no matching glyph): " + skippedNoGlyphToResetCount + "\r" +
            "Errors: " + errorCount;
    } else {
        msg +=
            "Glyph checkboxes updated: " + updatedCount + "\r" +
            "Skipped (no matching glyph): " + skippedNoGlyphToUpdateCount + "\r" +
            "Normalized spacing: " + adjustedSpacingCount + "\r" +
            "Errors: " + errorCount;
    }

    alert(msg);
})();
```

---

## Why this is stronger than the rectangle version

### Pros
- no anchored-object detection complexity
- no inline rectangle sizing/alignment issues
- update mode is simpler
- reset is simpler
- works naturally with text reflow
- easy to style globally with one character style

### Tradeoff
- depends on glyph availability in the chosen font

If your font doesn’t support `☐ ☑ ☒ ◩`, just swap the glyphs.

---

# Recommended production tweaks

## 1. Set a dedicated glyph font in `CH_CheckGlyph`
For example, a symbol-capable font.

You can also add this inside `ensureCharacterStyle()`:

```javascript
cs.appliedFont = "Arial Unicode MS";
```

or whatever font is installed and reliable in your environment.

## 2. Add state-specific character styles if desired
Right now, one character style is used for all states.

If you want:
- empty = black
- checked = green
- review = red

then I’d split this into:
- `CH_CheckGlyph_Empty`
- `CH_CheckGlyph_Checked`
- `CH_CheckGlyph_Indeterminate`
- `CH_CheckGlyph_Review`

and map state → character style exactly like the object-style version.

## 3. Prefer a visible separator
Thin space is elegant, but if your typography or export pipeline is touchy, use a normal space:

```javascript
var SPACE_AFTER_GLYPH = " ";
```

---

# My practical recommendation

If this were my production setup, I’d do:

- paragraph style = semantic checklist line
- marker text = source/import format
- glyph conversion = layout format
- metadata labels = reversibility/update safety
- one character style per state = visual control

That gives you a very clean editorial pipeline.

