                                continue;
                            }

                            updateExistingGlyph(glyphToUpdate);

                            if (ENSURE_SPACE_AFTER_GLYPH) {
                                if (ensureSingleThinSpaceAfterGlyph(para)) {
                                    adjustedSpacingCount++;
                                }
                            }

                            updatedCount++;
                        }
                    } catch (innerErr) {
                        errorCount++;
                    }
                }
            }
        },
        ScriptLanguage.JAVASCRIPT,
        undefined,
        UndoModes.ENTIRE_SCRIPT,
        (MODE === "convert")
            ? "Convert forgiving checklist markers to styled glyph checklist items"
            : (MODE === "reset")
                ? "Reset styled glyph checklist items to markers"
                : "Update styled glyph checklist items"
    );

    // =========================================================
    // Report
    // =========================================================
    var msg = "Done.\rMode: " + MODE + "\r";

    if (MODE === "convert") {
        msg +=
            "Glyph checkboxes inserted: " + convertedCount + "\r" +
            "Skipped (already converted): " + skippedAlreadyConvertedCount + "\r" +
            "Skipped (no recognizable marker): " + skippedWrongMarkerCount + "\r" +
            "Normalized messy prefixes: " + normalizedMessyPrefixCount + "\r" +
            "Normalized spacing: " + adjustedSpacingCount + "\r" +
            "Errors: " + errorCount;
    } else if (MODE === "reset") {
        msg +=
            "Glyph checkboxes reset to markers: " + resetCount + "\r" +
            "Skipped (no matching glyph): " + skippedNoGlyphToResetCount + "\r" +
            "Errors: " + errorCount;
    } else {
        msg +=
            "Glyph checkboxes updated: " + updatedCount + "\r" +
            "Skipped (no matching glyph): " + skippedNoGlyphToUpdateCount + "\r" +
            "Normalized spacing: " + adjustedSpacingCount + "\r" +
            "Errors: " + errorCount;
    }

    alert(msg);
})();
```

---

## What this improves

This version accepts all of these on convert:

- `[CB] text`
- `[CK]\ttext`
- `   [CR] text`
- ` [CI]`
- `[CB]text` if `ALLOW_MARKER_WITHOUT_SEPARATOR = true`

So the parser is no longer tied to exact canonical marker formatting.

---

## One important behavior note

This line:

```javascript
paragraph.characters.itemByRange(0, removeLen - 1).remove();
```

removes:

- any allowed leading whitespace
- the marker
- one accepted separator if present

That means a paragraph like:

```text
   [CR] Review this section
```

becomes:

```text
☒ Review this section
```

with the glyph inserted at true paragraph start.

That’s usually what you want.

---

## Best small refinements from here

If I were polishing this further, I’d do these next:

### 1. Preserve intentional indent whitespace
Right now, leading spaces before the marker are consumed as part of normalization.

If some imported text uses literal spaces for visual indentation, you may want to keep them. In that case, change removal so it deletes only from `markerStart` instead of from `0`.

### 2. Support lowercase markers
You could accept:

- `[cb]`
- `[ck]`

by uppercasing the parsed tag before mapping.

### 3. Reject false positives more carefully
If you ever have prose beginning with something like:

- `[CR]ITICAL`

the current parser would still read `[CR]` as a marker if it appears right at the start.

If that matters, require either:
- end of paragraph after marker, or
- a separator after marker, unless explicitly allowing no separator.

### 4. Add canonical reset style
Reset currently restores canonical markers like `[CK]\t`.
That’s good. It means reset gives you a consistent machine-friendly form, not the messy original form.

---

## My practical recommendation

For production, I’d use:

```javascript
var ALLOW_MARKER_WITHOUT_SEPARATOR = false;
```

That avoids accidental matches and still accepts the most common messy imports:

- leading spaces
- tab separator
- space separator

If you’re importing highly inconsistent text and want maximum tolerance, leave it `true`.

---

## If you want the strongest version

The next upgrade I’d suggest is a **GREP-based parser version** instead of manual string parsing, because then you can:

- scan only paragraph starts with a regex
- handle uppercase/lowercase cleanly
- normalize more patterns with fewer branches
- optionally batch-find before mutation

A good target pattern would be something like:

```regex
^\s*\[(CB|CK|CI|CR)\](?:\t| +|\u2009|\u2002|\u2003)?
```

That would be cleaner and easier to extend.

If you want, I can produce that next:
1. **GREP-based version**
2. **indent-preserving version**
3. **lowercase-tolerant version**
4. **all-in production version** with those combined

Let’s pursue the **all-in production version**.

That’s the most useful next step: combine the forgiving import behavior with the refinements that matter in real documents:

- GREP-style prefix detection logic
- preserves intentional indentation
- accepts lowercase markers
- avoids most false positives
- keeps canonical reset output
- still uses per-state character styles and metadata

Because ExtendScript/InDesign GREP APIs are a bit awkward for safe paragraph-by-paragraph mutation, I’m keeping the actual paragraph processing explicit, but the parser behavior is effectively regex-driven.

