            paragraph.insertionPoints[index].contents = glyph;
            var ch = paragraph.characters[index];

            try { ch.appliedCharacterStyle = charStyle; } catch (e1) {}
            setGlyphMetadata(ch, state);

            return ch;
        } catch (e) {
            return null;
        }
    }

    function ensureSingleThinSpaceAfterGlyphAtIndex(paragraph, glyphIndex) {
        try {
            if (paragraph.characters.length < (glyphIndex + 1)) return false;

            var glyphChar = paragraph.characters[glyphIndex];
            if (!isOurGlyphCharacter(glyphChar)) return false;

            if (paragraph.characters.length < (glyphIndex + 2)) {
                paragraph.insertionPoints[glyphIndex + 1].contents = SPACE_AFTER_GLYPH;
                return true;
            }

            var nextChar = paragraph.characters[glyphIndex + 1].contents;

            if (nextChar === SPACE_AFTER_GLYPH) return false;

            if (isSeparatorChar(nextChar)) {
                paragraph.characters[glyphIndex + 1].contents = SPACE_AFTER_GLYPH;
                return true;
            }

            paragraph.insertionPoints[glyphIndex + 1].contents = SPACE_AFTER_GLYPH;
            return true;
        } catch (e) {}

        return false;
    }

    function removeSpaceAfterGlyphIfPresentAtIndex(paragraph, glyphIndex) {
        try {
            if (paragraph.characters.length < (glyphIndex + 2)) return false;
            if (!isOurGlyphCharacter(paragraph.characters[glyphIndex])) return false;

            var nextChar = paragraph.characters[glyphIndex + 1].contents;
            if (isSeparatorChar(nextChar)) {
                paragraph.characters[glyphIndex + 1].remove();
                return true;
            }
        } catch (e) {}
        return false;
    }

    function restoreMarkerAtParagraphIndex(paragraph, index, marker) {
        try {
            paragraph.insertionPoints[index].contents = marker;
            return true;
        } catch (e) {
            return false;
        }
    }

    function updateExistingGlyph(characterRef) {
        var state = getGlyphState(characterRef);
        var charStyle = getCharacterStyleForState(state);

