                        if (MODE === "convert") {
                            var existingGlyph = getLeadingGlyphCharacter(para);

                            if (existingGlyph) {
                                skippedAlreadyConvertedCount++;
                                updateExistingGlyph(existingGlyph);

                                if (ENSURE_SPACE_AFTER_GLYPH) {
                                    if (ensureSingleThinSpaceAfterGlyphAtIndex(para, 0)) {
                                        adjustedSpacingCount++;
                                    }
                                }
                                continue;
                            }

                            var parsed = parseChecklistPrefix(para);
                            if (!parsed) {
                                skippedWrongMarkerCount++;
                                continue;
                            }

                            var insertionIndex = PRESERVE_LEADING_INDENTATION ? parsed.markerStart : 0;
                            if (PRESERVE_LEADING_INDENTATION && parsed.markerStart > 0) {
                                preservedIndentCount++;
                            }

                            if (!removeParsedChecklistPrefix(para, parsed)) {
                                errorCount++;
                                continue;
                            }

                            var inserted = insertGlyphAtParagraphIndex(para, insertionIndex, parsed.state);
                            if (!inserted) {
                                errorCount++;
                                continue;
                            }

                            if (ENSURE_SPACE_AFTER_GLYPH) {
                                if (ensureSingleThinSpaceAfterGlyphAtIndex(para, insertionIndex)) {
                                    adjustedSpacingCount++;
                                }
                            }

                            normalizedMessyPrefixCount++;
                            convertedCount++;
                        }

                        else if (MODE === "reset") {
                            var glyphChar = getLeadingGlyphCharacter(para);

                            if (!glyphChar) {
                                skippedNoGlyphToResetCount++;
                                continue;
                            }

                            var stateToRestore = getGlyphState(glyphChar);
                            if (!stateToRestore) stateToRestore = STATE_EMPTY;

                            var glyphIndex = 0;

                            removeSpaceAfterGlyphIfPresentAtIndex(para, glyphIndex);

                            try {
                                glyphChar.remove();
                            } catch (e1) {
                                errorCount++;
                                continue;
                            }

                            if (!restoreMarkerAtParagraphIndex(para, glyphIndex, markerForState(stateToRestore) || DEFAULT_RESET_MARKER)) {
                                errorCount++;
                                continue;
                            }

                            resetCount++;
                        }

                        else if (MODE === "update") {
                            var glyphToUpdate = getLeadingGlyphCharacter(para);

                            if (!glyphToUpdate) {
                                skippedNoGlyphToUpdateCount++;
                                continue;
                            }

                            updateExistingGlyph(glyphToUpdate);

                            if (ENSURE_SPACE_AFTER_GLYPH) {
                                if (ensureSingleThinSpaceAfterGlyphAtIndex(para, 0)) {
                                    adjustedSpacingCount++;
                                }
                            }

                            updatedCount++;
                        }
                    } catch (innerErr) {
                        errorCount++;
                    }
                }
            }
        },
        ScriptLanguage.JAVASCRIPT,
        undefined,
        UndoModes.ENTIRE_SCRIPT,
        (MODE === "convert")
            ? "Convert checklist markers to styled glyph checklist items"
            : (MODE === "reset")
                ? "Reset styled glyph checklist items to markers"
                : "Update styled glyph checklist items"
    );

    // =========================================================
    // Report
    // =========================================================
    var msg = "Done.\rMode: " + MODE + "\r";

    if (MODE === "convert") {
        msg +=
            "Glyph checkboxes inserted: " + convertedCount + "\r" +
            "Skipped (already converted): " + skippedAlreadyConvertedCount + "\r" +
            "Skipped (no recognizable marker): " + skippedWrongMarkerCount + "\r" +
            "Normalized prefixes: " + normalizedMessyPrefixCount + "\r" +
            "Preserved indents: " + preservedIndentCount + "\r" +
            "Normalized spacing: " + adjustedSpacingCount + "\r" +
            "Errors: " + errorCount;
    } else if (MODE === "reset") {
        msg +=
            "Glyph checkboxes reset to markers: " + resetCount + "\r" +
            "Skipped (no matching glyph): " + skippedNoGlyphToResetCount + "\r" +
            "Errors: " + errorCount;
    } else {
        msg +=
            "Glyph checkboxes updated: " + updatedCount + "\r" +
            "Skipped (no matching glyph): " + skippedNoGlyphToUpdateCount + "\r" +
            "Normalized spacing: " + adjustedSpacingCount + "\r" +
            "Errors: " + errorCount;
    }

    alert(msg);
})();
