                                continue;
                            }

                            var parsed = parseChecklistPrefix(para);
                            if (!parsed) {
                                skippedWrongMarkerCount++;
                                continue;
                            }

                            var insertionIndex = PRESERVE_LEADING_INDENTATION ? parsed.markerStart : 0;
                            if (PRESERVE_LEADING_INDENTATION && parsed.markerStart > 0) {
                                preservedIndentCount++;
                            }

                            if (!removeParsedChecklistPrefix(para, parsed)) {
                                errorCount++;
                                continue;
                            }

                            var inserted = insertGlyphAtParagraphIndex(para, insertionIndex, parsed.state);
                            if (!inserted) {
                                errorCount++;
                                continue;
                            }

                            if (ENSURE_SPACE_AFTER_GLYPH) {
                                if (ensureSingleThinSpaceAfterGlyphAtIndex(para, insertionIndex)) {
                                    adjustedSpacingCount++;
                                }
                            }

                            normalizedMessyPrefixCount++;
                            convertedCount++;
                        }

                        else if (MODE === "reset") {
                            var glyphInfo = getLeadingGlyphInfo(para);

                            if (!glyphInfo) {
                                skippedNoGlyphToResetCount++;
                                continue;
                            }

                            var glyphChar = glyphInfo.character;
                            var glyphIndex = glyphInfo.index;

                            var stateToRestore = getGlyphState(glyphChar);
